def countWildcardAnagramWindows(s, p):
    n, m = len(s), len(p)
    need = [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    have = [0] * 26
    excess = 0
    ans = 0
    for i in range(n):
        if s[i] != '?':
            c = ord(s[i]) - 97
            have[c] += 1
            if have[c] == need[c] + 1:
                excess += 1
        if i >= m and s[i - m] != '?':
            d = ord(s[i - m]) - 97
            if have[d] == need[d] + 1:
                excess -= 1
            have[d] -= 1
        if i >= m - 1 and excess == 0:
            ans += 1
    return ans
